                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[y for y,_ in cells]; xs=[x for _,x in cells]
                res.append({"col":col,"r0":min(ys),"c0":min(xs),"r1":max(ys),"c1":max(xs),
                            "pat":tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells)),"cells":cells})
    return res

def f(g):
    g=[row[:] for row in g]
    bg=g[0][0]
    S=shapes(g,bg)
    cnt=defaultdict(int)
    for s in S: cnt[s['col']]+=1
    # special shape: unique-count color, largest
    uniq=[s for s in S if cnt[s['col']]==1]
    sp=max(uniq,key=lambda s:len(s['cells']))
    pairs=defaultdict(list)
    for s in S: pairs[s['pat']].append(s)
    for pat,ss in pairs.items():
        if len(ss)==2:
            a,b=ss
            def inside(s): return s['r0']>=sp['r0'] and s['r1']<=sp['r1'] and s['c0']>=sp['c0'] and s['c1']<=sp['c1']
            ia,ib=inside(a),inside(b)
            out = b if ia and not ib else (a if ib and not ia else None)
            if out is not None:
                for y,x in out['cells']: g[y][x]=sp['col']
    return g

